package build

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"syscall"

	"github.com/KogenAI/kogen-coordinator/project"
	"github.com/KogenAI/kogen-loop/sys"
)

func modelRefusal(dir, reason string) error {
	return sys.Fail("candidate", "model_promotion_refused", "the maintained model directory "+filepath.ToSlash(dir)+" "+reason+
		"; nothing was written; inspect it, then restore a complete model, remove the directory or obtain fresh approval", 1)
}

// promoteModel gives the candidate its independent project specification. A missing or empty
// directory of the approved Intent's slug is filled, as one rename, from the approved source;
// a complete pair is kept; anything else is refused.
func (b *Attempt) promoteModel() error {
	m := b.intent.Model
	if m == nil || m.None {
		return nil
	}
	rel := filepath.ToSlash(filepath.Join(".kogen/models", b.Slug))
	dir := filepath.Join(b.Root, rel)
	info, err := os.Lstat(dir)
	switch {
	case err == nil:
		if !info.IsDir() {
			return modelRefusal(rel, "is not a directory")
		}
		entries, rerr := os.ReadDir(dir)
		if rerr != nil {
			return rerr
		}
		if len(entries) > 0 {
			return keepCompleteModel(rel, dir, entries)
		}
	case !os.IsNotExist(err):
		return err
	}
	if err := b.BaselineIntact(); err != nil {
		return err
	}
	if err := b.approvalIntact(); err != nil {
		return modelRefusal(rel, "cannot be filled: the approval is not the one this Build pinned ("+err.Error()+")")
	}
	data, err := os.ReadFile(filepath.Join(b.Root, m.Path))
	if err != nil {
		return modelRefusal(rel, "cannot be filled: the approved model source "+m.Path+" cannot be read ("+err.Error()+")")
	}
	if fileDigest(b.Root, m.Path) != b.BaselineDigests[m.Path] || len(bytes.TrimSpace(data)) == 0 {
		return modelRefusal(rel, "cannot be filled: the model source "+m.Path+" is not the approved, non-empty source")
	}
	spec := *m
	spec.Path = rel + "/model.qnt"
	record, err := json.MarshalIndent(spec, "", "  ")
	if err != nil {
		return err
	}
	local := filepath.Join(b.Root, ".kogen/local")
	if err = os.MkdirAll(local, 0755); err != nil {
		return err
	}
	stage, err := os.MkdirTemp(local, "model-promotion-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(stage)
	if err = os.WriteFile(filepath.Join(stage, "model.qnt"), data, 0644); err != nil {
		return err
	}
	if err = os.WriteFile(filepath.Join(stage, "model.json"), append(record, '\n'), 0644); err != nil {
		return err
	}
	if err = os.MkdirAll(filepath.Dir(dir), 0755); err != nil {
		return err
	}
	if err = os.Chmod(stage, 0755); err != nil {
		return err
	}
	// syscall.Rename replaces an empty directory in one step; os.Rename refuses an existing one.
	return syscall.Rename(stage, dir)
}

// keepCompleteModel accepts exactly a model source and a readable record of it.
func keepCompleteModel(rel, dir string, entries []os.DirEntry) error {
	names := map[string]bool{}
	for _, e := range entries {
		if !e.Type().IsRegular() {
			return modelRefusal(rel, "holds "+e.Name()+", which is not a regular file")
		}
		names[e.Name()] = true
	}
	if len(entries) != 2 || !names["model.qnt"] || !names["model.json"] {
		var have []string
		for _, e := range entries {
			have = append(have, e.Name())
		}
		return modelRefusal(rel, "is neither empty nor a complete model (holds "+strings.Join(have, ", ")+")")
	}
	data, err := os.ReadFile(filepath.Join(dir, "model.json"))
	if err != nil {
		return err
	}
	var spec project.ModelSpec
	if err = json.Unmarshal(data, &spec); err != nil || spec.Path != rel+"/model.qnt" {
		return modelRefusal(rel, "holds a model record that does not describe "+rel+"/model.qnt")
	}
	return nil
}

func maintainedModels(root string) ([]project.ModelSpec, error) {
	dir := filepath.Join(root, ".kogen/models")
	entries, err := os.ReadDir(dir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var models []project.ModelSpec
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, entry.Name(), "model.json"))
		if err != nil {
			return nil, err
		}
		var spec project.ModelSpec
		if err = json.Unmarshal(data, &spec); err != nil {
			return nil, err
		}
		models = append(models, spec)
	}
	return models, nil
}

