+// archived finds a file of that name anywhere in the local storage outside the Build runs.
+func archived(root, name string) []byte {
+	var found []byte
+	filepath.WalkDir(filepath.Join(root, ".kogen/local"), func(p string, d os.DirEntry, err error) error {
+		if err == nil && !d.IsDir() && d.Name() == name && !strings.Contains(filepath.ToSlash(p), "/runs/") {
+			found, _ = os.ReadFile(p)
+		}
+		return nil
+	})
+	return found
+}

